 explode(x,z,r=8,source){if(source&&!source.active)return;const y=this.world.heightAt(x,z);if(source){source.active=false;source.hp=0;if(source.view){source.view.visible=false;}this.emit('destroy',source.tag);}this.world.fire.ignite(x,z,r);this.ctx.physics.explode([x,y+1,z],{radius:r,impulse:10});this.ctx.particles.burst('smoke',[x,y+2,z],{count:30});this.ctx.particles.burst('impact',[x,y+1,z],{count:25,colors:['sand','orange','red']});this.sound.play('explosion',.7);if(Math.hypot(x-this.pos.x,z-this.pos.z)<80)this.ctx.engine.shake.add(.55);for(const a of this.actors.list)if(!a.dead&&a.kind==='soldier'){const d=Math.hypot(a.x-x,a.z-z);if(d<r)this.actors.damage(a,220*(1-d/r),1);}const d=Math.hypot(this.pos.x-x,this.pos.z-z);if(d<r)this.body.damage(90*(1-d/r),'fire');for(const v of this.vehicles.list){if(v.dead)continue;const p=this.vehicles.position(v),vd=Math.hypot(p.x-x,p.z-z);if(vd<r)this.vehicles.damage(v,220*(1-vd/r));}for(const o of this.world.objects)if(o!==source&&o.active&&o.explosive&&Math.hypot(o.x-x,o.z-z)<r*.7)o.hp-=120;}
