 const candidates=[];const dir=this.direction();for(const o of this.world.objects){if(o.id==='harrow-ledger'&&this.mission.current?.id!=='m7')continue;if(o.id==='harrow'&&this.mission.current?.id!=='m9')continue;if(!o.active||o.explosive||o.tag==='border'||o.tag==='payroll'&&!this.vehicles.list.find(v=>v.id==='pay-truck')?.dead)continue;const dx=o.x-this.pos.x,dz=o.z-this.pos.z,d=Math.hypot(dx,dz);if(d>o.r)continue;const dot=(dx*dir.x+dz*dir.z)/(d||1);if(dot<.7&&d>1.5)continue;if(o.site&&!this.world.siteById(o.site)?.cleared)continue;candidates.push({text:o.name,action:'use',hold:o.tag==='cage'?2:0,object:o,d});}
